// Every failure, ranked, with the effort and user-impact grid: start where fixes are cheap and users won't notice.

import { useState } from "react"
import { Link } from "@/lib/router"
import { SEVERITIES, priority, severityWeight } from "@/lib/model"
import { useReport } from "@/components/report/ReportContext"
import { FixList, Footer } from "@/components/report/lists"
import { ProductMark } from "@/components/report/ui"

const LEVELS = ["Low", "Medium", "High"]
const SEVERITY_COLOUR: Record<string, string> = { Critical: "var(--mt-fail)", High: "var(--mt-high)", Medium: "var(--mt-warn)", Low: "var(--mt-skip)", Info: "var(--mt-info)" }

export default function ActionPlanPage() {
  const { model, explore } = useReport()
  const [cell, setCell] = useState<[string, string] | null>(null)
  const failing = model.failing
  const inCell = (impact: string, effort: string) => failing.filter((t) => (t.UserImpact || "Medium") === impact && (t.ImplementationCost || "Medium") === effort)
  const list = cell ? inCell(cell[0], cell[1]).sort((a, b) => priority(b) - priority(a)) : model.ranked
  const byProduct = model.products.map((p) => ({ p, rows: p.rows.filter((t) => t.Result === "Failed") })).filter((x) => x.rows.length).sort((a, b) => b.rows.length - a.rows.length)
  const hasLevels = failing.some((t) => t.UserImpact || t.ImplementationCost)

  return (
    <div className="mt-wrap">
      <div className="mt-head">
        <div className="mt-eyebrow">Action plan</div>
        <h1 className="mt-h1">{failing.length} failures, ranked by what to fix first</h1>
        <p className="mt-lead">Each test says how much its fix disrupts users and how much work it is. Start in the green corner: fixes that are cheap and that users won't notice.</p>
      </div>
      <div className="mt-grid mt-g2" style={{ alignItems: "start" }}>
        {hasLevels && (
          <div className="mt-card mt-pad mt-sec">
            <h2 className="mt-h2">Effort and user impact</h2>
            <div className="mt-matrix">
              <span />
              {LEVELS.map((l) => <span key={l} className="ax">Effort {l}</span>)}
              {LEVELS.flatMap((impact) => [
                <span key={`a${impact}`} className="ax">User impact {impact}</span>,
                ...LEVELS.map((effort) => {
                  const rows = inCell(impact, effort)
                  const on = !!cell && cell[0] === impact && cell[1] === effort
                  return (
                    <button key={impact + effort} type="button" className={`mt-cell${impact === "Low" && effort === "Low" ? " best" : ""}`} aria-pressed={on} onClick={() => setCell(on ? null : [impact, effort])}>
                      <b className="mt-num">{rows.length}</b><span>{rows.filter((t) => severityWeight(t.Severity) >= 3).length} high severity</span>
                    </button>
                  )
                }),
              ])}
            </div>
            <p className="mt-note">{cell ? <>Showing user impact {cell[0]}, effort {cell[1]}. <button type="button" className="mt-link" style={{ border: 0, background: "none", padding: 0 }} onClick={() => setCell(null)}>Show all</button></> : "Choose a cell to list its tests."}</p>
          </div>
        )}
        {byProduct.length > 0 && (
          <div className="mt-card mt-pad mt-sec">
            <h2 className="mt-h2">Where the work is</h2>
            {byProduct.map(({ p, rows }) => (
              <Link key={p.key} to={`/product/${encodeURIComponent(p.key)}`} style={{ display: "grid", gridTemplateColumns: "22px minmax(0,1fr) 1.2fr 34px", gap: 10, alignItems: "center", fontSize: 13 }}>
                <ProductMark product={p.key} /><span>{p.name}</span>
                <span className="mt-bar thin">{SEVERITIES.map((s) => { const n = rows.filter((t) => t.Severity === s).length; return n ? <i key={s} style={{ width: `${(n / rows.length) * 100}%`, background: SEVERITY_COLOUR[s] }} /> : null })}</span>
                <b className="mt-num" style={{ textAlign: "right" }}>{rows.length}</b>
              </Link>
            ))}
            <div className="mt-legend">{["High", "Medium", "Low"].map((s) => <span key={s}><i style={{ background: SEVERITY_COLOUR[s] }} />{s}</span>)}</div>
          </div>
        )}
      </div>
      <FixList rows={list} limit={50} />
      {list.length > 50 && <p className="mt-note">{list.length - 50} more in <a href="#/tests" className="mt-link" onClick={(e) => { e.preventDefault(); explore({ filters: { Result: ["Failed"] } }) }}>the test list</a>.</p>}
      <Footer />
    </div>
  )
}
const reportDataElementId = "maester-report-data"

export async function loadReportData(): Promise<unknown> {
  const embedded = document.getElementById(reportDataElementId)?.textContent?.trim()

  if (import.meta.env.DEV) {
    // ?sample=2x loads a Maester 2.x result, to check that the report still renders one.
    const sample = new URLSearchParams(window.location.search).get("sample")
    if (sample === "2x") {
      return (await import("@/lib/testResultsLegacy")).testResults
    }
    const results = (await import("@/lib/testResults")).testResults
    const { withSampleExtras } = await import("@/lib/sampleExtras")
    // ?sample=tenants shows a merged report of five tenants.
    if (sample === "tenants") {
      const merged = (await import("@/lib/sampleTenants")).sampleTenants(results)
      return { Tenants: merged.Tenants.map((t: Record<string, unknown>, i: number) => withSampleExtras(t, i)) }
    }
    // ?sample=one and ?sample=suite show how the report looks for a run of one test or of the CIS suite.
    if (sample === "one" || sample === "suite") {
      const tests = results.Tests.filter((t) => (sample === "one" ? t.Id === "CIS.M365.1.1.1" : t.Suite === "CIS"))
      return { ...results, Tests: tests, Packs: [], InvokeCommand: sample === "one" ? "Invoke-Maester -TestId CIS.M365.1.1.1" : "Invoke-Maester -Suite CIS" }
    }
    return withSampleExtras(results)
  }

  if (!embedded) {
    throw new Error("Report data was not embedded in the generated HTML file")
  }

  const json = embedded.replace(/^(?:const|let|var)\s+\w+\s*=\s*/, "")
  return JSON.parse(json) as unknown
}
// Dev only: what a real run adds that the sample result lacks. Earlier runs' counts (Previous.History) for the
// trend, and AffectedObjects for "What Maester checked". Both are made from the result itself, the same on every load.

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Raw = Record<string, any>

const USERS = ["Adele Vance", "Alex Wilber", "Bagul Atayewa", "Bob Leaf", "Damien Bowden", "Diego Siciliani", "Emergency Access", "Gael Colas", "Isaiah Langer", "Joshua Fernando", "Lee Gu", "Megan Bowen", "Miriam Graham", "Nestor Wilke", "Patti Fernandez", "Tyler Chan"]
const POLICIES = ["Require MFA for admins", "Block legacy authentication", "Require MFA for all users", "Require compliant device for admins", "Block sign-in from risky locations", "Require password change for high-risk users", "Sign-in frequency for admins", "Block device code flow"]
const GROUPS = ["All Staff", "Break glass accounts", "Finance", "Helpdesk", "Privileged access reviewers"]
const APPS = ["Contoso HR", "Expense Tracker", "Graph Explorer", "Maester", "Microsoft Graph Command Line Tools", "Payroll Connector", "Salesforce", "ServiceNow", "Slack", "Zoom"]
const REGISTRATIONS = ["contoso-api", "contoso-web", "invoice-bot", "legacy-sync", "reporting-dashboard", "test-app"]
const ROLES = ["Global Administrator", "Privileged Role Administrator", "Security Administrator", "Exchange Administrator", "Application Administrator", "User Administrator"]
const RULES = ["External sender warning", "Block auto-forward to external"]

function ids(result: Raw, product: string, features: string[]) {
  return (result.Tests as Raw[]).filter((t) => t.Product === product && features.includes(t.Feature)).map((t) => String(t.Id))
}

export function withSampleExtras(result: Raw, seed = 0): Raw {
  if (!Array.isArray(result?.Tests)) return result
  const pick = (list: string[], i: number) => list.filter((_, j) => (j + i + seed) % 3 !== 0).slice(0, 4)
  const objects: Raw[] = []
  const add = (type: string, system: string, names: string[], tests: string[]) => names.forEach((n, i) => objects.push({ System: system, Type: type, Id: `${type}-${i}`, DisplayName: n, Tests: pick(tests, i), Referenced: true }))
  add("User", "EntraID", USERS, ids(result, "entra", ["roles", "privileged-identity-management"]).concat(ids(result, "microsoft-365", ["administrative-accounts"])))
  add("ConditionalAccessPolicy", "EntraID", POLICIES, ids(result, "entra", ["conditional-access"]))
  add("Group", "EntraID", GROUPS, ids(result, "entra", ["groups", "identity-governance"]))
  add("ServicePrincipal", "EntraID", APPS, ids(result, "entra", ["applications", "app-consent"]))
  add("AppRegistration", "EntraID", REGISTRATIONS, ids(result, "entra", ["applications", "app-consent"]))
  add("DirectoryRole", "EntraID", ROLES, ids(result, "entra", ["roles", "privileged-identity-management"]))
  add("TransportRule", "ExchangeOnline", RULES, ids(result, "exchange", ["mail-flow"]))
  for (const path of ["users", "groups", "servicePrincipals", "applications", "directoryRoles", "domains", "organization", "subscribedSkus", "policies/authorizationPolicy", "identity/conditionalAccess/policies", "policies/authenticationMethodsPolicy", "roleManagement/directory/roleAssignments"]) {
    objects.push({ System: "MicrosoftGraph", Type: path, Id: path, DisplayName: path, Tests: [], Referenced: false })
  }

  // Weekly runs before the previous one, with a few more failures the further back they go.
  const previous = result.Previous
  let withHistory = previous
  if (previous && !previous.History) {
    // The newest entry is the previous run itself; the rest go back a week at a time.
    const before = Object.values(previous.Results || {}) as string[]
    const count = (r: string) => before.filter((v) => v === r).length
    const history = Array.from({ length: 9 }, (_, i) => {
      const at = new Date(previous.ExecutedAt)
      at.setDate(at.getDate() - 7 * i)
      const drift = i === 0 ? 0 : Math.round(i * (2.6 + (seed % 3)) + ((i * 7 + seed) % 5))
      return { ExecutedAt: at.toISOString(), Total: before.length, Passed: Math.max(0, count("Passed") - drift), Failed: count("Failed") + drift, Investigate: count("Investigate"), Error: count("Error"), Skipped: count("Skipped"), NotRun: count("NotRun") }
    })
    withHistory = { ...previous, History: history }
  }
  return { ...result, AffectedObjects: result.AffectedObjects ?? objects, Previous: withHistory }
}
// The views the sidebar lists. Each is listed only when it has something to show, so a run of one test gets a
// short sidebar and a full run gets every product, framework and pack. A pack's view is built from its rows'
// Fields (ZTA: Pillar, Category), so a new pack needs no code here.

import { frameworkLabel, frameworkTally, tally, type Model, type Row } from "@/lib/model"
import type { IconName } from "./ui"

export interface ViewDef {
  path: string
  group: "Tenants" | "Summary" | "Products" | "Frameworks" | "Packs" | "Reports"
  title: string
  product?: string
  code?: string
  icon?: IconName
  count?: number
  bad?: boolean
}

// A product, framework or pack none of whose tests ran (every one skipped or not run) has nothing to show.
const ran = (rows: Row[]) => rows.some((t) => t.Result !== "Skipped" && t.Result !== "NotRun")

export function buildViews(model: Model, extra: { affectedObjects: boolean; attachments: { title: string; path: string }[]; tenants?: number }): ViewDef[] {
  const views: ViewDef[] = []
  // A merged result of several tenants starts with the page that compares them; the sidebar lists the tenants under it.
  if (extra.tenants && extra.tenants > 1) views.push({ path: "/tenants", group: "Tenants", title: "All tenants", icon: "tenant", count: extra.tenants })
  const focused = model.focused
  // Summary: the pages that cover the whole run, so the action plan, changes and affected objects are never below
  // a long list of products.
  views.push({ path: "/", group: "Summary", title: focused ? (model.rows.length === 1 ? "Result" : "Results") : "Overview", icon: "home" })
  if (model.failing.length >= 2) views.push({ path: "/plan", group: "Summary", title: "Action plan", icon: "fix", count: model.failing.length, bad: true })
  if (!focused) views.push({ path: "/tests", group: "Summary", title: "All tests", icon: "result", count: model.rows.length })
  if (!focused && model.previous && model.changes.newlyFailing.length + model.changes.fixed.length > 0) {
    views.push({ path: "/changes", group: "Summary", title: "Changes since last run", icon: "history", count: model.changes.newlyFailing.length, bad: true })
  }
  if (extra.affectedObjects) views.push({ path: "/affected-objects", group: "Summary", title: "Affected objects", icon: "resource" })
  if (!focused) {
    for (const p of model.products) if (ran(p.rows)) views.push({ path: `/product/${encodeURIComponent(p.key)}`, group: "Products", title: p.name, product: p.key, count: tally(p.rows).Failed, bad: true })
    for (const f of model.frameworks) views.push({ path: `/framework/${encodeURIComponent(f.Key)}`, group: "Frameworks", title: frameworkLabel(f), icon: "framework", count: frameworkTally(model, f).Failed, bad: true })
    if (model.rows.some((t) => t.Mitre.length)) views.push({ path: "/attack", group: "Frameworks", title: "MITRE ATT&CK", icon: "attack" })
  }
  for (const p of model.packs) views.push({ path: `/pack/${encodeURIComponent(p.Id)}`, group: "Packs", title: p.Name, code: p.Code, count: tally(p.rows).Failed, bad: true })
  for (const a of extra.attachments) views.push({ path: a.path, group: "Reports", title: a.title, icon: "report" })
  views.push({ path: "/run", group: "Reports", title: "Run details", icon: "duration" })
  return views
}
// The model of the selected tenant's result, which test is open, and the test list's filters, for every view.
// A merged result of several tenants has a model for each; the tenants page compares them.
// A test opens in the sheet when the URL's anchor names it (#/plan#CIS.M365.1.1.1), so a link to it can be
// shared; the 2.x form #/CIS.M365.1.1.1 still works. The list a test was opened from sets the order that the
// sheet's previous and next buttons (and the arrow keys) step through.

import { createContext, useCallback, useContext, useMemo, useState, type ReactNode } from "react"
import { useTenant } from "@/context/TenantContext"
import { useLocation, useNavigate } from "@/lib/router"
import { buildModel, sortTests, type Model } from "@/lib/model"

export interface Explorer {
  q: string
  filters: Record<string, string[]>
  group: string
}

interface ReportContextValue {
  model: Model
  models: Model[]
  multi: boolean
  tenantIndex: number
  /** Switch tenant, then go to a page of that tenant (and open a test when the anchor names one). */
  selectTenant: (index: number, to?: string | { pathname: string; hash?: string }) => void
  openId: string | null
  /** Open a test. `list` is the order of the tests around it, as the view shows them; `replace` keeps the history
   * to one entry while stepping through them. */
  openTest: (id: string, list?: string[], replace?: boolean) => void
  /** The tests the open one was opened among, in order. */
  sequence: string[]
  closeTest: () => void
  explorer: Explorer
  explore: (patch: Partial<Explorer>) => void
  setExplorer: (patch: Partial<Explorer>) => void
  tab: string
  setTab: (tab: string) => void
}

const ReportContext = createContext<ReportContextValue | null>(null)

function decode(value: string) {
  try { return decodeURIComponent(value) } catch { return value }
}

export function ReportProvider({ children }: { children: ReactNode }) {
  const { tenants, selectedIndex, setSelectedIndex } = useTenant()
  const models = useMemo(() => tenants.map(buildModel), [tenants])
  const model = models[selectedIndex] ?? models[0]
  const location = useLocation()
  const navigate = useNavigate()
  const [explorer, setExplorerState] = useState<Explorer>({ q: "", filters: {}, group: "none" })
  const [tab, setTab] = useState("finding")
  const [list, setList] = useState<string[]>([])

  const fromHash = location.hash.length > 1 ? decode(location.hash.slice(1)) : null
  const fromPath = decode(location.pathname.replace(/^\/+|\/+$/g, ""))
  const openId = fromHash && model.byId.has(fromHash) ? fromHash : model.byId.has(fromPath) ? fromPath : null

  const openTest = useCallback((id: string, ids?: string[], replace?: boolean) => {
    if (ids) setList(ids)
    const path = model.byId.has(decode(location.pathname.replace(/^\/+|\/+$/g, ""))) ? "/" : location.pathname
    navigate({ pathname: path, hash: `#${encodeURIComponent(id)}` }, replace ? { replace: true } : undefined)
  }, [location.pathname, model, navigate])
  // A test opened from a link, search or another tenant steps through every test in the usual order.
  const sequence = useMemo(() => (openId && list.includes(openId) ? list : sortTests(model.rows).map((t) => t.Id)), [list, openId, model])
  const closeTest = useCallback(() => {
    const path = model.byId.has(decode(location.pathname.replace(/^\/+|\/+$/g, ""))) ? "/" : location.pathname
    navigate({ pathname: path }, { replace: true })
  }, [location.pathname, model, navigate])
  const selectTenant = useCallback((index: number, to?: string | { pathname: string; hash?: string }) => {
    setSelectedIndex(index)
    if (to) navigate(to)
  }, [navigate, setSelectedIndex])
  const setExplorer = useCallback((patch: Partial<Explorer>) => setExplorerState((e) => ({ ...e, ...patch })), [])
  const explore = useCallback((patch: Partial<Explorer>) => {
    setExplorerState({ q: "", filters: {}, group: "none", ...patch })
    navigate("/tests")
  }, [navigate])

  const value = useMemo(
    () => ({ model, models, multi: models.length > 1, tenantIndex: selectedIndex, selectTenant, openId, openTest, sequence, closeTest, explorer, explore, setExplorer, tab, setTab }),
    [model, models, selectedIndex, selectTenant, openId, openTest, sequence, closeTest, explorer, explore, setExplorer, tab],
  )
  return <ReportContext.Provider value={value}>{children}</ReportContext.Provider>
}

export function useReport() {
  const context = useContext(ReportContext)
  if (!context) throw new Error("useReport must be used within ReportProvider")
  return context
}

// The first page. A full run gets the summary: pass rate, what to fix first, products, frameworks, what an
// attacker could do, why tests did not run, and packs. A run of one to three tests gets the tests themselves.

import { Link } from "@/lib/router"
import { REASONS, RESULTS, RESULT_LABEL, SEVERITIES, SEVERITY_MEANING, fixCommand, frameworkLabel, isQuickWin, maesterVersion, serviceName, severityWeight, tally, type Row } from "@/lib/model"
import { useReport } from "@/components/report/ReportContext"
import { DetailBody, DetailHeader, DetailTabs } from "@/components/report/TestDetail"
import { FixList, Footer } from "@/components/report/lists"
import { AttackAreas, Checked, Kpis, Posture, Trend } from "@/components/report/overview"
import { Bar, Cmd, ProductMark, formatDate, plural } from "@/components/report/ui"

const SEVERITY_COLOUR: Record<string, string> = { Critical: "var(--mt-fail)", High: "var(--mt-high)", Medium: "var(--mt-warn)", Low: "var(--mt-skip)", Info: "var(--mt-info)" }

function Ring({ rate, scored }: { rate: number | null; scored: number }) {
  const c = 2 * Math.PI * 62
  return (
    <div className="mt-ring">
      <svg width="148" height="148" viewBox="0 0 148 148" role="img" aria-label={`Pass rate ${rate ?? 0}%`}>
        <circle cx="74" cy="74" r="62" fill="none" stroke="var(--mt-subtle)" strokeWidth="14" />
        {scored > 0 && <circle cx="74" cy="74" r="62" fill="none" stroke="var(--mt-fail)" strokeWidth="14" strokeDasharray={`${c} ${c}`} transform="rotate(-90 74 74)" />}
        {scored > 0 && <circle cx="74" cy="74" r="62" fill="none" stroke="var(--mt-pass)" strokeWidth="14" strokeDasharray={`${(c * (rate ?? 0)) / 100} ${c}`} transform="rotate(-90 74 74)" />}
      </svg>
      <div className="c"><b className="mt-num">{rate ?? "–"}{rate !== null ? "%" : ""}</b><span>passed of {scored}<br />scored tests</span></div>
    </div>
  )
}

function Focused() {
  const { model } = useReport()
  const rows = model.rows
  const first = rows[0]
  const before = model.previous?.Results[first.Id]
  const verdict: Record<string, string> = { Passed: "It passed.", Failed: "It failed.", Investigate: "It needs a closer look.", Error: "It could not run because of an error.", Skipped: "It was skipped.", NotRun: "It did not run." }
  const tenant = String(model.result.TenantName || "the tenant").replace(/\.$/, "")
  const lead = rows.length === 1
    ? `You ran one test against ${tenant}. ${verdict[first.Result] || ""}${before && before !== first.Result && model.previous ? ` It ${before === "Passed" || before === "Failed" ? before.toLowerCase() : `was ${RESULT_LABEL[before]?.toLowerCase()}`} on ${formatDate(model.previous.ExecutedAt)}, so something changed since then.` : ""}`
    : `You ran ${rows.length} tests against ${tenant}: ${RESULTS.filter((r) => model.all[r]).map((r) => `${model.all[r]} ${RESULT_LABEL[r].toLowerCase()}`).join(", ")}.`
  const more: [string, string][] = []
  if (first.Feature) more.push([`Every test for ${model.featureName(first)}`, `Invoke-Maester -Feature ${first.Feature}`])
  if (first.Product && model.hasAttributes) more.push([`Every ${model.productName(first.Product)} test`, `Invoke-Maester -Product ${first.Product}`])
  if (first.Benchmark && first.Suite) more.push([`The whole ${frameworkLabel({ Key: String(first.Benchmark.Framework), Name: String(first.Benchmark.Framework) })} benchmark`, `Invoke-Maester -Suite ${first.Suite}`])
  more.push(["Everything Maester checks", "Invoke-Maester"])
  return (
    <div className="mt-wrap">
      <div className="mt-head">
        <div className="mt-eyebrow">{rows.length === 1 ? "One test" : plural(rows.length, "test")} · {formatDate(model.result.ExecutedAt, true)}</div>
        <h1 className="mt-h1">{rows.length === 1 ? first.Title : `${model.all.Failed} of ${rows.length} tests failed`}</h1>
        <p className="mt-lead">{lead}</p>
      </div>
      <div className="mt-focus">
        <div style={{ display: "flex", flexDirection: "column", gap: 16, minWidth: 0 }}>
          {rows.map((t) => <div key={t.Id} className="mt-panel"><DetailHeader test={t} inline /><DetailTabs test={t} /><DetailBody test={t} /></div>)}
        </div>
        <aside style={{ display: "flex", flexDirection: "column", gap: 14 }}>
          <div className="mt-card mt-pad mt-sec">
            <h2 className="mt-h2">Check more of this tenant</h2>
            <p className="mt-note">The report grows with the run: products, frameworks and the action plan appear once there are more than a few tests.</p>
            {more.map(([label, command]) => <div key={command} style={{ display: "flex", flexDirection: "column", gap: 5 }}><span style={{ fontSize: 13, fontWeight: 550 }}>{label}</span><Cmd command={command} wrap /></div>)}
          </div>
          <div className="mt-card mt-pad mt-sec">
            <h2 className="mt-h2">This run</h2>
            <dl className="mt-kv" style={{ gridTemplateColumns: "1fr" }}>
              {([["Command", model.result.InvokeCommand], ["Duration", model.result.TotalDuration], ["Maester", maesterVersion(model.result)], ["Account", model.result.Account]] as [string, unknown][]).filter(([, v]) => v).map(([k, v]) => <div key={k}><dt>{k}</dt><dd className={k === "Command" ? "mt-mono" : ""} style={k === "Command" ? { fontSize: 11.5 } : undefined}>{String(v)}</dd></div>)}
            </dl>
          </div>
        </aside>
      </div>
      <Footer />
    </div>
  )
}

export default function OverviewPage() {
  const { model, explore } = useReport()
  if (!model.rows.length) return <div className="mt-wrap"><div className="mt-head"><h1 className="mt-h1">No tests ran</h1><p className="mt-lead">The result has no tests. Check the selection in Run details.</p></div></div>
  if (model.focused) return <Focused />

  const { all, failing } = model
  const nSources = new Set(model.rows.map((t) => (t.Package ? t.Package.Id : t.Suite || t.Source))).size
  const highFailing = failing.filter((t) => severityWeight(t.Severity) >= 3 && t.Severity !== "Info").length
  const reach = all.scored ? Math.round(((all.scored - failing.filter((t) => t.Severity !== "Info").length + highFailing) / all.scored) * 100) : null
  const severityCounts = SEVERITIES.map((s) => [s, failing.filter((t) => t.Severity === s).length] as [string, number]).filter(([, n]) => n)
  const maxSeverity = Math.max(1, ...severityCounts.map(([, n]) => n))
  const notRun = model.rows.filter((t) => t.Result === "Skipped" || t.Result === "NotRun" || t.Result === "Error")
  const reasons = new Map<string, { code: string; command: string; rows: Row[] }>()
  for (const t of notRun) {
    const code = t.ReasonCode || (t.Result === "Error" ? "TestError" : "NotApplicable")
    const command = fixCommand({ ...t, ReasonCode: code })
    const key = `${code}|${code === "ServiceNotConnected" ? command : ""}`
    if (!reasons.has(key)) reasons.set(key, { code, command, rows: [] })
    reasons.get(key)!.rows.push(t)
  }
  const reasonRows = [...reasons.values()].sort((a, b) => b.rows.length - a.rows.length).slice(0, 6)
  const notRunCount = all.Skipped + all.NotRun + all.Error

  return (
    <div className="mt-wrap">
      <div className="mt-head">
        <div className="mt-eyebrow">Security report · {formatDate(model.result.ExecutedAt, true)}</div>
        <h1 className="mt-h1">{model.result.TenantName || "The tenant"} passed {all.rate ?? 0}% of the checks that ran</h1>
        <p className="mt-lead">
          {plural(all.total, "test")}{model.hasAttributes ? ` from ${nSources} ${nSources === 1 ? "suite" : "suites and packs"}` : ""} ran{model.products.length ? ` against ${plural(model.products.length, "product")}` : ""}. <b>{all.Failed} failed</b>, {all.Investigate} need a closer look, and {notRunCount} did not run because a service, licence or permission was missing.
          {highFailing > 0 && reach !== null ? <> Fixing the {plural(highFailing, "high-severity failure")} would take the pass rate to <b>{reach}%</b>.</> : null}
        </p>
      </div>

      <Kpis />

      <div className="mt-hero">
        <div className="mt-card mt-pad">
          <div className="mt-score">
            <Ring rate={all.rate} scored={all.scored} />
            <div className="mt-counts">
              {RESULTS.map((r) => <button key={r} type="button" className="mt-count" onClick={() => explore({ filters: { Result: [r] } })}><b className="mt-num">{all[r]}</b><span><i className={`mt-b-${r}`} />{RESULT_LABEL[r]}</span></button>)}
            </div>
          </div>
          {model.previous && (
            <div className="mt-delta">
              <Link to="/changes"><b className="mt-up mt-num">+{model.changes.newlyFailing.length}</b> new failures since {formatDate(model.previous.ExecutedAt)}</Link>
              <Link to="/changes"><b className="mt-down mt-num">{model.changes.fixed.length}</b> fixed</Link>
              <Link to="/changes"><b className="mt-num">{model.changes.added.length}</b> tests added</Link>
            </div>
          )}
          <Trend />
        </div>
        <div className="mt-card mt-pad mt-sec">
          <div className="mt-sechead"><h2 className="mt-h2">Failed by severity</h2>{failing.length >= 2 && <Link to="/plan">Open the action plan →</Link>}</div>
          <div className="mt-sevrows">
            {severityCounts.map(([s, n]) => (
              <button key={s} type="button" className="mt-sevrow" onClick={() => explore({ filters: { Result: ["Failed"], Severity: [s] } })}>
                <span className={`mt-sev mt-s-${s}`}>{s}</span><span className="track"><i style={{ width: `${(n / maxSeverity) * 100}%`, background: SEVERITY_COLOUR[s] }} /></span><b className="mt-num" style={{ textAlign: "right" }}>{n}</b>
              </button>
            ))}
            {!severityCounts.length && <p className="mt-note">Nothing failed.</p>}
          </div>
          {severityCounts.length > 0 && <dl className="mt-sevdef">{severityCounts.flatMap(([s]) => [<dt key={`t${s}`}>{s}</dt>, <dd key={`d${s}`}>{SEVERITY_MEANING[s]}</dd>])}</dl>}
          {failing.length > 0 && <p className="mt-note">{failing.filter(isQuickWin).length} of the {failing.length} failures are quick wins: little effort to fix, and users won't notice.</p>}
        </div>
      </div>

      {failing.length > 0 && (
        <section className="mt-sec">
          <div className="mt-sechead"><h2 className="mt-h2">Fix these first</h2>{failing.length > 6 && <Link to="/plan">All {failing.length} failures, ranked →</Link>}</div>
          <FixList rows={model.ranked} limit={6} />
          <p className="mt-note">Ranked by severity, then by how little the fix costs and how little it disrupts users.</p>
        </section>
      )}

      {model.products.length >= 2 && (
        <section className="mt-sec">
          <div className="mt-sechead"><h2 className="mt-h2">Products</h2><a href="#/tests" onClick={(e) => { e.preventDefault(); explore({ group: "product" }) }}>Compare in the test list →</a></div>
          <div className="mt-grid mt-g3">
            {model.products.map((p) => {
              const c = tally(p.rows)
              const fromPacks = p.rows.filter((t) => t.Package).length
              return (
                <Link key={p.key} to={`/product/${encodeURIComponent(p.key)}`} className="mt-card mt-prod">
                  <div className="top"><ProductMark product={p.key} /><b>{p.name}</b><span className="n">{plural(c.total, "test")}</span></div>
                  <Bar tally={c} />
                  <div className="mt-stats"><span><b className="mt-num">{c.Failed}</b> failed</span><span><b className="mt-num">{c.Passed}</b> passed</span><span><b className="mt-num">{c.Skipped + c.NotRun}</b> not run</span>{c.scored >= 5 && <span style={{ marginLeft: "auto" }}><b className="mt-num">{c.rate}%</b></span>}{fromPacks > 0 && <span style={{ flexBasis: "100%", fontSize: 11.5 }}>{fromPacks} from packs</span>}</div>
                </Link>
              )
            })}
          </div>
        </section>
      )}

      <Posture />

      <AttackAreas />

      <Checked />

      {(notRun.length > 0 || model.packs.length > 0) && (
        <div className="mt-grid mt-g2">
          {notRun.length > 0 && (
            <section className="mt-sec">
              <div className="mt-sechead"><h2 className="mt-h2">Why {plural(notRunCount, "test")} did not run</h2><Link to="/run">Run details →</Link></div>
              <div className="mt-card mt-whylist">
                {reasonRows.map((g) => (
                  <div key={g.code + g.command} className="mt-whyrow">
                    <div>
                      <b>{g.code === "ServiceNotConnected" ? `${serviceName(g.command.replace("Connect-Maester -Service ", ""))} not connected` : (REASONS[g.code] || [g.code])[0]}</b> <span className="mt-muted mt-num">· {plural(g.rows.length, "test")}</span>
                      <p>{(REASONS[g.code] || ["", ""])[1]}</p>
                    </div>
                    {g.command ? <Cmd command={g.command} /> : <button type="button" className="mt-btn" onClick={() => explore({ q: "", filters: { Result: [...new Set(g.rows.map((t) => t.Result))] } })}>Show tests</button>}
                  </div>
                ))}
              </div>
            </section>
          )}
          {model.packs.length > 0 && (
            <section className="mt-sec">
              <div className="mt-sechead"><h2 className="mt-h2">Packs in this run</h2><a href="https://maester.dev/docs/packs" target="_blank" rel="noopener noreferrer">Find more packs ↗</a></div>
              <div className="mt-grid" style={{ gap: 10 }}>
                {model.packs.map((p) => {
                  const c = tally(p.rows)
                  return (
                    <Link key={p.Id} to={`/pack/${encodeURIComponent(p.Id)}`} className="mt-card mt-packcard">
                      <div className="ph"><span className="mt-code">{p.Code}</span><b style={{ fontSize: 14 }}>{p.Name}</b>{p.Version && <span className="mt-muted mt-mono" style={{ fontSize: 11.5, marginLeft: "auto" }}>v{p.Version}</span>}</div>
                      {p.Description && <p>{p.Description}</p>}
                      {p.Status !== "Ready" ? <p>Did not run: {p.Reason}</p> : <Bar tally={c} thin />}
                      <div className="mt-legend"><span>{c.Failed} failed</span><span>{c.Passed} passed</span><span>{plural(c.total, "test")}</span>{p.BuiltIn && <span className="mt-badge">Official</span>}{p.Risk && <span className="mt-badge">{p.Risk} risk</span>}</div>
                    </Link>
                  )
                })}
              </div>
            </section>
          )}
        </div>
      )}
      <Footer />
    </div>
  )
}
// The overview's summary pieces: headline cards, the pass-rate trend, the compliance posture grid, the attacker
// outcomes as tabs, and the objects the run checked.

import { useState, type KeyboardEvent } from "react"
import { Link, useNavigate } from "@/lib/router"
import { OUTCOMES, REASONS, frameworkLabel, isQuickWin, tally, type Row } from "@/lib/model"
import { objectsChecked, postureGrid, runHistory, type RunPoint } from "@/lib/insights"
import { ICON_BASE } from "@/lib/featureIcons"
import { band } from "@/lib/tenants"
import { useReport } from "./ReportContext"
import { FixList } from "./lists"
import { Bar, Icon, ProductMark, formatDate, plural, type IconName } from "./ui"

const SEVERITY_DOT: Record<string, string> = { Critical: "var(--mt-fail)", High: "var(--mt-high)", Medium: "var(--mt-warn)", Low: "var(--mt-skip)" }

function Delta({ now, before }: { now: number | null; before: number | null | undefined }) {
  if (now === null || before === null || before === undefined) return null
  const d = now - before
  if (d === 0) return <span className="mt-dl flat" title="Same as the previous run">→ 0</span>
  return <span className={`mt-dl ${d > 0 ? "good" : "bad"}`} title={`${d > 0 ? "Up" : "Down"} ${Math.abs(d)} points since the previous run`}>{d > 0 ? "↗" : "↘"} {Math.abs(d)}</span>
}

interface Chip { label: string; n: number | string; colour?: string; onClick?: () => void; to?: string }

function Kpi({ icon, label, value, note, noteTone, chips, onClick }: { icon: IconName; label: string; value: number | string; note?: string; noteTone?: "up" | "down"; chips: Chip[]; onClick?: () => void }) {
  // The card's own action is a button laid under its content, so the chips stay buttons and links of their own
  // rather than controls nested inside a button.
  return (
    <div className={`mt-card mt-kpi${onClick ? " click" : ""}`}>
      {onClick && <button type="button" className="mt-kpi-hit" onClick={onClick} aria-label={`${label}: ${value}. Show these tests`} />}
      <span className="k"><Icon name={icon} />{label}</span>
      <span className="v"><b className="mt-num">{value}</b>{note && <small className={noteTone === "up" ? "mt-up" : noteTone === "down" ? "mt-down" : "mt-muted"}>{note}</small>}</span>
      {chips.length > 0 && (
        <span className="chips">
          {chips.map((c) => {
            const body = <>{c.colour && <i style={{ background: c.colour }} />}{c.label} <b className="mt-num">{c.n}</b></>
            if (c.to) return <Link key={c.label} to={c.to} className="mt-kchip" onClick={(e) => e.stopPropagation()}>{body}</Link>
            if (c.onClick) return <button key={c.label} type="button" className="mt-kchip" onClick={(e) => { e.stopPropagation(); c.onClick!() }}>{body}</button>
            return <span key={c.label} className="mt-kchip">{body}</span>
          })}
        </span>
      )}
    </div>
  )
}

/** Headline cards, each opening the tests behind its number. */
export function Kpis() {
  const { model, explore } = useReport()
  const navigate = useNavigate()
  const failing = model.failing
  const severe = failing.filter((t) => t.Severity === "Critical" || t.Severity === "High")
  const quick = failing.filter(isQuickWin)
  const notRun = model.rows.filter((t) => t.Result === "Skipped" || t.Result === "NotRun" || t.Result === "Error")
  const reasons = new Map<string, number>()
  for (const t of notRun) { const code = t.ReasonCode || (t.Result === "Error" ? "TestError" : "NotApplicable"); reasons.set(code, (reasons.get(code) || 0) + 1) }
  const grid = postureGrid(model)
  // A framework none of whose requirements has a result has no rate, and is left out of the average.
  const rated = grid.filter((g) => g.now.rate !== null && g.now.rate !== undefined)
  const newly = model.changes.newlyFailing.length
  const failedFilter = { Result: ["Failed"] }
  return (
    <div className="mt-kpis">
      <Kpi icon="finding" label="Failed" value={failing.length} note={model.previous ? `+${newly} new` : undefined} noteTone={newly ? "up" : undefined} onClick={() => explore({ filters: failedFilter })}
        chips={["Critical", "High", "Medium", "Low"].map((s) => ({ label: s, n: failing.filter((t) => t.Severity === s).length, colour: SEVERITY_DOT[s], onClick: () => explore({ filters: { Result: ["Failed"], Severity: [s] } }) })).filter((c) => c.n)} />
      <Kpi icon="severity" label="Critical and high" value={severe.length} note={model.previous ? `${model.changes.newlyFailing.filter((t) => severe.includes(t)).length} new` : undefined} onClick={() => explore({ filters: { Result: ["Failed"], Severity: ["Critical", "High"] } })}
        chips={[{ label: "Quick to fix", n: severe.filter(isQuickWin).length }, { label: "With ATT&CK", n: severe.filter((t) => t.Mitre.length).length }]} />
      <Kpi icon="effort" label="Quick wins" value={quick.length} note="low effort, low impact" onClick={quick.length ? () => navigate("/plan") : undefined}
        chips={[{ label: "Fixed since last run", n: model.changes.fixed.length }]} />
      <Kpi icon="service" label="Did not run" value={notRun.length} onClick={() => explore({ filters: { Result: [...new Set(notRun.map((t) => t.Result))] } })}
        chips={[...reasons.entries()].sort((a, b) => b[1] - a[1]).slice(0, 3).map(([code, n]) => ({ label: (REASONS[code] || [code])[0].replace(/\.$/, ""), n }))} />
      {grid.length > 0 && (
        <Kpi icon="framework" label="Frameworks" value={rated.length ? `${Math.round(rated.reduce((s, g) => s + (g.now.rate as number), 0) / rated.length)}%` : "–"} note="requirements met, on average"
          chips={grid.map((g) => ({ label: frameworkLabel(g.framework).replace(/ Microsoft 365$/, ""), n: `${g.now.rate ?? "–"}%`, to: `/framework/${encodeURIComponent(g.framework.Key)}` }))} />
      )}
    </div>
  )
}

/** The pass rate of this run and the earlier ones the output folder holds, as a line. */
// How the report was made: the run, the connections, the suites and packs, and links to the system and config pages.

import { Link } from "@/lib/router"
import { maesterVersion } from "@/lib/model"
import { useReport } from "@/components/report/ReportContext"
import { Footer } from "@/components/report/lists"
import { Cmd, formatDate, plural } from "@/components/report/ui"

export default function RunPage() {
  const { model } = useReport()
  const r = model.result
  const version = maesterVersion(r)
  const sources = new Map<string, number>()
  for (const t of model.rows) { const k = model.packOf(t)?.Name || t.Suite || t.Source || "Other"; sources.set(k, (sources.get(k) || 0) + 1) }
  const connections: { Service: string; Status: string; Details?: string }[] = Array.isArray(r.ConnectionSummary) ? r.ConnectionSummary : []
  const files = r.OutputFiles ? Object.entries(r.OutputFiles).filter(([k, v]) => v && k !== "OutputFolder" && k !== "OutputFolderFileName") : []
  const runRows: [string, unknown][] = [
    ["Started", r.ExecutedAt ? formatDate(r.ExecutedAt, true) : null], ["Duration", r.TotalDuration],
    ["Maester", version ? `${version}${r.LatestVersion && String(r.LatestVersion) !== version ? ` (${r.LatestVersion} available)` : ""}` : null],
    ["Account", r.Account], ["Tenant ID", r.TenantId], ["Dry run", r.Selection?.DryRun ? "Yes" : null],
  ]
  return (
    <div className="mt-wrap">
      <div className="mt-head"><div className="mt-eyebrow">Run details</div><h1 className="mt-h1">How this report was made</h1></div>
      <div className="mt-grid mt-g2">
        <div className="mt-card mt-pad mt-sec">
          <h2 className="mt-h2">Run</h2>
          <dl className="mt-kv">{runRows.filter(([, v]) => v).map(([k, v]) => <div key={k}><dt>{k}</dt><dd className={k === "Tenant ID" ? "mt-mono" : ""} style={k === "Tenant ID" ? { fontSize: 11.5 } : undefined}>{String(v)}</dd></div>)}</dl>
          {r.InvokeCommand && <Cmd command={String(r.InvokeCommand)} wrap />}
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}><Link className="mt-btn" to="/system">System and modules</Link><Link className="mt-btn" to="/config">Maester config</Link></div>
        </div>
        {connections.length > 0 && (
          <div className="mt-card mt-pad mt-sec">
            <h2 className="mt-h2">Connections</h2>
            <div className="mt-links">{connections.map((c) => <div key={c.Service}><span>{c.Service}{c.Details && c.Status !== "Connected" ? <span className="mt-muted" style={{ display: "block", fontSize: 12, fontFamily: "var(--mt-font)" }}>{c.Details}</span> : null}</span><span className={`mt-pill ${c.Status === "Connected" ? "mt-r-Passed" : "mt-r-Skipped"}`} style={{ fontFamily: "var(--mt-font)" }}>{c.Status}</span></div>)}</div>
          </div>
        )}
        <div className="mt-card mt-pad mt-sec">
          <h2 className="mt-h2">Suites and packs</h2>
          <div className="mt-links">{[...sources.entries()].sort((a, b) => b[1] - a[1]).map(([k, n]) => <div key={k}><span>{k}</span><span>{plural(n, "test")}</span></div>)}</div>
        </div>
        {files.length > 0 && (
          <div className="mt-card mt-pad mt-sec">
            <h2 className="mt-h2">Files written</h2>
            <div className="mt-links">{files.map(([k, v]) => <div key={k}><span className="mt-mono" style={{ fontSize: 12, overflowWrap: "anywhere" }}>{String(v)}</span><span /></div>)}</div>
          </div>
        )}
      </div>
      <Footer />
    </div>
  )
}

/* The report's design language, shared with maester.dev: zinc neutrals, one accent (Ember) for the current page and
   links, near-black buttons, red/orange/amber/green only for results and severity, IDs and commands in monospace.
   Layout: a sticky top bar, the view sidebar, one scrolling main column; a test opens in a side sheet.
   Every class starts with mt- so it never meets a Tailwind utility of the same name. */

:root {
  --mt-paper: #ffffff; --mt-canvas: #fafafa; --mt-subtle: #f4f4f5; --mt-line: #e4e4e7; --mt-line-2: #f0f0f1;
  --mt-ink: #18181b; --mt-ink-2: #3f3f46; --mt-ink-3: #71717a; --mt-brand: #111113; --mt-brand-ink: #ffffff;
  --mt-ember: #d22c31; --mt-ember-soft: rgba(210, 44, 49, .07); --mt-ember-ink: #b4232a;
  --mt-pass: #16a34a; --mt-pass-bg: #dcfce7; --mt-pass-ink: #15803d;
  --mt-fail: #dc2626; --mt-fail-bg: #fee2e2; --mt-fail-ink: #b91c1c;
  --mt-warn: #d97706; --mt-warn-bg: #fef3c7; --mt-warn-ink: #92400e;
  --mt-high: #ea580c; --mt-high-bg: #ffedd5; --mt-high-ink: #9a3412;
  --mt-info: #2563eb; --mt-info-bg: #eff6ff; --mt-info-ink: #1d4ed8;
  --mt-skip: #a1a1aa; --mt-skip-bg: #f4f4f5; --mt-skip-ink: #52525b;
  --mt-inv: #7c3aed; --mt-inv-bg: #f3e8ff; --mt-inv-ink: #6d28d9;
  --mt-shadow: 0 1px 2px rgba(0, 0, 0, .04), 0 8px 24px rgba(0, 0, 0, .06);
  --mt-font: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
  --mt-mono: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
}
.dark {
  --mt-paper: #09090b; --mt-canvas: #111113; --mt-subtle: #18181b; --mt-line: #27272a; --mt-line-2: #1f1f22;
  --mt-ink: #fafafa; --mt-ink-2: #d4d4d8; --mt-ink-3: #a1a1aa; --mt-brand: #fafafa; --mt-brand-ink: #09090b;
  --mt-ember: #ff6b6f; --mt-ember-soft: rgba(255, 107, 111, .10); --mt-ember-ink: #ff8a8d;
  --mt-pass: #22c55e; --mt-pass-bg: rgba(34, 197, 94, .14); --mt-pass-ink: #4ade80;
  --mt-fail: #ef4444; --mt-fail-bg: rgba(239, 68, 68, .16); --mt-fail-ink: #f87171;
  --mt-warn: #f59e0b; --mt-warn-bg: rgba(245, 158, 11, .15); --mt-warn-ink: #fbbf24;
