.mt-badge.good { background: var(--mt-pass-bg); color: var(--mt-pass-ink); }
.mt-badge.bad { background: var(--mt-fail-bg); color: var(--mt-fail-ink); }

/* Product marks: Microsoft's product icons, unchanged and beside the product name; a neutral tile otherwise. */
.mt-pm { width: 22px; height: 22px; flex: none; border-radius: 6px; display: grid; place-items: center; font: 650 9px/1 var(--mt-font); letter-spacing: -.02em; color: var(--mt-ink-2); background: var(--mt-subtle); border: 1px solid var(--mt-line); }
