.mt-fixrow { display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; gap: 14px; align-items: center; padding: 13px 18px; border: 0; border-top: 1px solid var(--mt-line-2); text-align: left; background: none; width: 100%; }
