.mt-fixrow .rank { font: 500 12px var(--mt-mono); color: var(--mt-ink-3); }
.mt-fixrow .t { font-weight: 600; font-size: 14px; line-height: 1.35; }
.mt-fixrow .m { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin-top: 5px; font-size: 12px; color: var(--mt-ink-3); }
.mt-fixrow .why { display: flex; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }

.mt-prod { display: flex; flex-direction: column; gap: 12px; padding: 16px 18px; text-align: left; width: 100%; }
.mt-prod:hover, .mt-tile:hover, .mt-packcard:hover { border-color: var(--mt-ink-3); }
.mt-prod .top { display: flex; align-items: center; gap: 10px; }
.mt-prod .top b { font-size: 14.5px; font-weight: 650; }
.mt-prod .top .n { margin-left: auto; font: 500 12px var(--mt-mono); color: var(--mt-ink-3); }
.mt-stats { display: flex; gap: 12px; font-size: 12.5px; color: var(--mt-ink-3); flex-wrap: wrap; }
.mt-stats b { color: var(--mt-ink); font-weight: 600; }

.mt-fwrow { display: grid; grid-template-columns: minmax(170px, 1.2fr) minmax(160px, 2fr) auto; gap: 18px; align-items: center; padding: 14px 18px; border-top: 1px solid var(--mt-line-2); }
.mt-fwrow:first-child { border-top: 0; }
.mt-fwrow:hover { background: var(--mt-canvas); }
.mt-fwrow .nm b { display: block; font-weight: 600; font-size: 14px; }
.mt-fwrow .nm span { font-size: 12px; color: var(--mt-ink-3); }
.mt-fwrow .fig { font: 500 12.5px var(--mt-mono); color: var(--mt-ink-2); text-align: right; white-space: nowrap; }

.mt-tiles { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 200px), 1fr)); gap: 10px; }
.mt-tile { border: 1px solid var(--mt-line); border-radius: 12px; padding: 12px 14px; display: flex; flex-direction: column; gap: 8px; text-align: left; background: var(--mt-paper); }
.mt-tile b { font-size: 13px; font-weight: 600; line-height: 1.3; }
.mt-tile .f { display: flex; justify-content: space-between; font-size: 12px; color: var(--mt-ink-3); }
.mt-tile .d { font-size: 12px; color: var(--mt-ink-3); line-height: 1.4; }

.mt-whylist { display: flex; flex-direction: column; }
.mt-whyrow { display: flex; flex-direction: column; align-items: flex-start; gap: 8px; padding: 13px 18px; border-top: 1px solid var(--mt-line-2); }
.mt-whyrow:first-child { border-top: 0; }
.mt-whyrow b { font-weight: 600; }
.mt-whyrow p { margin: 2px 0 0; font-size: 12.5px; color: var(--mt-ink-3); }
.mt-cmd { display: inline-flex; align-items: center; gap: 8px; font: 12px var(--mt-mono); background: var(--mt-canvas); border: 1px solid var(--mt-line); border-radius: 8px; padding: 5px 9px; color: var(--mt-ink-2); max-width: 100%; overflow-x: auto; white-space: nowrap; }
.mt-cmd button { border: 0; background: none; padding: 0; color: var(--mt-ink-3); font-size: 11px; }
.mt-cmd button:hover { color: var(--mt-ink); }
.mt-cmd.wrap { white-space: normal; overflow-wrap: anywhere; justify-content: space-between; align-items: flex-start; }

.mt-packcard { display: flex; flex-direction: column; gap: 10px; padding: 16px 18px; text-align: left; width: 100%; }
.mt-packcard .ph { display: flex; align-items: center; gap: 10px; }
.mt-packcard p { margin: 0; font-size: 12.5px; color: var(--mt-ink-3); }

/* Test list */
.mt-explorer { display: grid; grid-template-columns: 220px minmax(0, 1fr); gap: 20px; align-items: start; }
.mt-facets { display: flex; flex-direction: column; gap: 18px; position: sticky; top: 80px; }
.mt-facet h5 { margin: 0 0 6px; font: 600 11px var(--mt-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--mt-ink-3); display: flex; gap: 6px; align-items: center; }
.mt-facet label { display: flex; align-items: center; gap: 8px; font-size: 13px; padding: 3px 2px; color: var(--mt-ink-2); cursor: pointer; }
