.mt-facet input { accent-color: var(--mt-ember); }
.mt-toolbar { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; }
.mt-input { border: 1px solid var(--mt-line); border-radius: 9px; padding: 8px 11px; font: inherit; font-size: 13.5px; background: var(--mt-paper); color: var(--mt-ink); min-width: 0; flex: 1 1 240px; }
select.mt-input { flex: 0 0 auto; }
.mt-tablewrap { overflow-x: auto; border: 1px solid var(--mt-line); border-radius: 14px; }
.mt-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.mt-table th { text-align: left; font: 600 11px var(--mt-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--mt-ink-3); padding: 10px 14px; border-bottom: 1px solid var(--mt-line); background: var(--mt-canvas); white-space: nowrap; }
.mt-table td { padding: 10px 14px; border-bottom: 1px solid var(--mt-line-2); vertical-align: middle; }
.mt-table tr:last-child td { border-bottom: 0; }
.mt-table tbody tr.click { cursor: pointer; }
.mt-table tbody tr.click:hover td { background: var(--mt-canvas); }
.mt-table td.ttl { min-width: 260px; font-weight: 500; }
.mt-table .grp td { background: var(--mt-subtle); font-weight: 650; font-size: 12.5px; }
.mt-table .grp td span { font-weight: 400; color: var(--mt-ink-3); }

/* Action plan */
.mt-matrix { display: grid; grid-template-columns: 90px repeat(3, minmax(0, 1fr)); gap: 8px; font-size: 12.5px; }
.mt-matrix .ax { display: flex; align-items: center; justify-content: center; color: var(--mt-ink-3); font: 500 11px var(--mt-mono); text-transform: uppercase; letter-spacing: .06em; text-align: center; }
.mt-cell { border: 1px solid var(--mt-line); border-radius: 12px; padding: 12px; min-height: 96px; display: flex; flex-direction: column; gap: 6px; text-align: left; background: var(--mt-paper); }
.mt-cell:hover { border-color: var(--mt-ink-3); }
.mt-cell b { font-size: 24px; font-weight: 650; letter-spacing: -.02em; }
.mt-cell span { color: var(--mt-ink-3); }
.mt-cell.best { background: var(--mt-pass-bg); border-color: transparent; }
.mt-cell.best b, .mt-cell.best span { color: var(--mt-pass-ink); }
.mt-cell[aria-pressed="true"] { outline: 2px solid var(--mt-ember); outline-offset: 1px; }

/* Frameworks */
.mt-reqgroup { border: 1px solid var(--mt-line); border-radius: 14px; overflow: hidden; }
.mt-reqgroup summary { list-style: none; display: grid; grid-template-columns: minmax(0, 1fr) 200px auto; gap: 16px; align-items: center; padding: 12px 18px; cursor: pointer; background: var(--mt-canvas); }
