.mt-req { display: grid; grid-template-columns: 130px minmax(0, 1fr) auto; gap: 14px; align-items: center; padding: 10px 18px; border-top: 1px solid var(--mt-line-2); font-size: 13px; width: 100%; background: none; border-left: 0; border-right: 0; border-bottom: 0; text-align: left; }
button.mt-req:hover { background: var(--mt-canvas); }
.mt-req .rid { font: 12px var(--mt-mono); color: var(--mt-ink-2); display: flex; gap: 6px; align-items: center; flex-wrap: wrap; }
.mt-req .tests { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.mt-gap { color: var(--mt-ink-3); font-style: italic; }
.mt-seg { display: inline-flex; border: 1px solid var(--mt-line); border-radius: 9px; padding: 2px; gap: 2px; background: var(--mt-canvas); flex-wrap: wrap; }
.mt-seg button { border: 0; background: none; padding: 5px 10px; border-radius: 7px; font-size: 12.5px; color: var(--mt-ink-2); }
.mt-seg button[aria-pressed="true"] { background: var(--mt-paper); color: var(--mt-ink); font-weight: 600; box-shadow: 0 1px 2px rgba(0, 0, 0, .08); }

/* ATT&CK */
.mt-attack { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(150px, 1fr); gap: 8px; overflow-x: auto; padding-bottom: 6px; }
.mt-tac { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.mt-tac h6 { margin: 0 0 2px; font-size: 12px; font-weight: 650; line-height: 1.3; min-height: 32px; }
.mt-tac h6 span { display: block; font: 11px var(--mt-mono); color: var(--mt-ink-3); font-weight: 400; }
.mt-tech { border-radius: 9px; padding: 8px 9px; font-size: 12px; line-height: 1.3; text-align: left; border: 1px solid transparent; width: 100%; }
.mt-tech .id { font: 10.5px var(--mt-mono); opacity: .85; display: block; margin-bottom: 2px; }
.mt-tech.fail { background: var(--mt-fail-bg); color: var(--mt-fail-ink); }
.mt-tech.pass { background: var(--mt-pass-bg); color: var(--mt-pass-ink); }
.mt-tech.part { background: var(--mt-warn-bg); color: var(--mt-warn-ink); }
.mt-tech.none { background: var(--mt-subtle); color: var(--mt-ink-3); }

/* Test detail */
.mt-scrim { position: fixed; inset: 0; background: rgba(9, 9, 11, .35); z-index: 40; }
.mt-sheet { position: fixed; top: 0; right: 0; bottom: 0; width: min(760px, 100%); background: var(--mt-paper); color: var(--mt-ink); z-index: 41; border-left: 1px solid var(--mt-line); box-shadow: var(--mt-shadow); display: flex; flex-direction: column; font: 14px/1.5 var(--mt-font); }
.mt-sheet-btns { position: absolute; top: 14px; right: 14px; display: flex; gap: 6px; z-index: 1; }
.mt-detail-head { padding: 18px 22px 14px; display: flex; flex-direction: column; gap: 10px; }
.mt-detail-head h2 { font-size: 20px; letter-spacing: -.015em; line-height: 1.3; margin: 0; }
.mt-detail-body { overflow-y: auto; padding: 18px 22px 40px; display: flex; flex-direction: column; gap: 22px; flex: 1; min-width: 0; }
.mt-detail-body h3 { font: 600 12px var(--mt-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--mt-ink-3); margin: 0 0 8px; }
.mt-facts { display: flex; flex-wrap: wrap; gap: 6px; }
.mt-fact { display: inline-flex; align-items: center; gap: 7px; border: 1px solid var(--mt-line); border-radius: 9px; padding: 4px 9px; font-size: 12.5px; background: var(--mt-paper); }
.mt-fact .k { color: var(--mt-ink-3); }
.mt-fact b { font-weight: 600; }
.mt-tabs { display: flex; gap: 2px; border-bottom: 1px solid var(--mt-line); padding: 0 22px; overflow-x: auto; scrollbar-width: none; flex: none; }
.mt-tabs button { border: 0; background: none; padding: 11px 10px 10px; font-size: 13px; color: var(--mt-ink-3); border-bottom: 2px solid transparent; white-space: nowrap; display: inline-flex; gap: 6px; align-items: center; }
.mt-tabs button:hover { color: var(--mt-ink); }
.mt-tabs button[aria-selected="true"] { color: var(--mt-ink); font-weight: 600; border-bottom-color: var(--mt-ember); }
.mt-tabs .n { font: 500 11px var(--mt-mono); color: var(--mt-ink-3); background: var(--mt-subtle); border-radius: 99px; padding: 0 6px; }
.mt-dgroup h4 { margin: 0 0 4px; font: 600 11px var(--mt-mono); letter-spacing: .08em; text-transform: uppercase; color: var(--mt-ink-3); }
.mt-drow { display: grid; grid-template-columns: 20px 130px minmax(0, 1fr); gap: 10px; align-items: start; padding: 9px 0; border-bottom: 1px solid var(--mt-line-2); font-size: 13px; }
.mt-drow .k { color: var(--mt-ink-3); }
.mt-drow .v { min-width: 0; overflow-wrap: anywhere; }
.mt-drow .mt-ai { margin-top: 2px; }
.mt-links { display: flex; flex-direction: column; gap: 2px; }
.mt-links > * { display: flex; justify-content: space-between; gap: 12px; padding: 8px 0; border-bottom: 1px solid var(--mt-line-2); font-size: 13px; background: none; border-left: 0; border-right: 0; border-top: 0; text-align: left; width: 100%; }
.mt-links > * > span:last-child { font-family: var(--mt-mono); color: var(--mt-ink-3); font-size: 12px; }
.mt-callout { border: 1px solid var(--mt-line); background: var(--mt-canvas); border-radius: 12px; padding: 12px 14px; font-size: 13px; line-height: 1.55; display: flex; gap: 10px; align-items: flex-start; }
.mt-callout.warn { border-color: var(--mt-warn-bg); background: var(--mt-warn-bg); color: var(--mt-warn-ink); }
.mt-kv { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 200px), 1fr)); gap: 0 22px; margin: 0; }
.mt-kv div { display: flex; justify-content: space-between; gap: 12px; padding: 8px 0; border-bottom: 1px solid var(--mt-line-2); font-size: 13px; }
.mt-kv dt { color: var(--mt-ink-3); } .mt-kv dd { margin: 0; text-align: right; font-weight: 500; overflow-wrap: anywhere; }
.mt-focus { display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: 20px; align-items: start; }
.mt-panel { border: 1px solid var(--mt-line); border-radius: 14px; overflow: hidden; display: flex; flex-direction: column; min-width: 0; }

/* Markdown from test guides and results */
.mt-md { font-size: 13.5px; line-height: 1.65; color: var(--mt-ink-2); min-width: 0; overflow-wrap: anywhere; }
.mt-md h1, .mt-md h2, .mt-md h3, .mt-md h4, .mt-md h5 { font-size: 13.5px; color: var(--mt-ink); margin: 14px 0 6px; text-transform: none; letter-spacing: 0; font-family: var(--mt-font); }
.mt-md p { margin: 0 0 10px; }
.mt-md ol, .mt-md ul { margin: 0 0 10px; padding-left: 20px; }
.mt-md ol { list-style: decimal; } .mt-md ul { list-style: disc; }
.mt-md a { color: var(--mt-ember-ink); text-decoration: underline; text-underline-offset: 2px; }
.mt-md code { font-family: var(--mt-mono); font-size: 12px; background: var(--mt-subtle); border-radius: 5px; padding: 1px 5px; }
.mt-md pre { background: var(--mt-canvas); border: 1px solid var(--mt-line); border-radius: 10px; padding: 10px 12px; overflow-x: auto; }
.mt-md pre code { background: none; padding: 0; }
.mt-md table { display: block; overflow-x: auto; border-collapse: collapse; font-size: 12.5px; margin: 0 0 10px; max-width: 100%; }
.mt-md th, .mt-md td { border: 1px solid var(--mt-line); padding: 6px 10px; text-align: left; }
.mt-md th { background: var(--mt-canvas); font-weight: 600; }

/* Search and popovers */
.mt-pal { position: fixed; inset: 0; z-index: 50; display: flex; justify-content: center; align-items: flex-start; padding: 12vh 16px 16px; background: rgba(9, 9, 11, .35); }
.mt-pal .box { width: min(640px, 100%); background: var(--mt-paper); color: var(--mt-ink); border: 1px solid var(--mt-line); border-radius: 14px; box-shadow: var(--mt-shadow); overflow: hidden; font: 14px/1.5 var(--mt-font); }
.mt-pal input { width: 100%; border: 0; border-bottom: 1px solid var(--mt-line); padding: 14px 16px; font: inherit; font-size: 15px; background: var(--mt-paper); color: var(--mt-ink); outline: none; }
.mt-pal ul { list-style: none; margin: 0; padding: 6px; max-height: 52vh; overflow-y: auto; }
.mt-pal li button { display: flex; gap: 10px; align-items: center; width: 100%; border: 0; background: none; padding: 8px 10px; border-radius: 8px; text-align: left; font-size: 13.5px; color: var(--mt-ink); }
.mt-pal li button:hover, .mt-pal li button[data-on="true"] { background: var(--mt-subtle); }
.mt-pal li .k { font: 11.5px var(--mt-mono); color: var(--mt-ink-3); margin-left: auto; white-space: nowrap; }
.mt-pop { position: fixed; z-index: 45; top: 60px; right: 16px; width: min(380px, calc(100% - 32px)); background: var(--mt-paper); color: var(--mt-ink); border: 1px solid var(--mt-line); border-radius: 14px; box-shadow: var(--mt-shadow); padding: 16px; display: flex; flex-direction: column; gap: 12px; font: 14px/1.5 var(--mt-font); }
.mt-pop h3 { font-size: 14px; font-weight: 650; margin: 0; }
.mt-pop p { margin: 0; font-size: 13px; color: var(--mt-ink-2); }
.mt-pop .opt { display: flex; flex-direction: column; gap: 6px; }
.mt-pop .opt > * { display: flex; justify-content: space-between; align-items: center; gap: 10px; border: 1px solid var(--mt-line); background: var(--mt-paper); border-radius: 10px; padding: 9px 12px; text-align: left; font-size: 13px; }
.mt-pop .opt > *:hover { background: var(--mt-subtle); }
.mt-pop .opt small { color: var(--mt-ink-3); font-size: 11.5px; }
.mt-toast { position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%); background: var(--mt-brand); color: var(--mt-brand-ink); padding: 9px 14px; border-radius: 10px; font-size: 13px; z-index: 60; box-shadow: var(--mt-shadow); }
.mt-foot { font-size: 12px; color: var(--mt-ink-3); border-top: 1px solid var(--mt-line); padding-top: 16px; display: flex; gap: 16px; flex-wrap: wrap; justify-content: space-between; }
.mt-empty { padding: 28px; text-align: center; color: var(--mt-ink-3); }

@media (max-width: 1080px) {
  .mt-hero, .mt-focus { grid-template-columns: minmax(0, 1fr); }

