// Writes report/src/lib/sampleSteps.ts: Steps and Goals for the dev sample, following sections 6 and 7.2 of
// docs/proposals/defenders-path.md closely enough for a fixture. Not shipped; the engine (M3) writes the real thing.
import fs from "fs"
const root = process.argv[2]
const src = fs.readFileSync(`${root}/report/src/lib/testResults.ts`, "utf8")
const start = src.indexOf("export const testResults = ") + 27
const result = (0, eval)("(" + src.slice(start, src.indexOf("\n}\n", start) + 2) + ")")
const inventory = JSON.parse(fs.readFileSync(process.argv[3], "utf8"))
const cat = {}
for (const f of ["entra", "intune", "defender"]) for (const s of JSON.parse(fs.readFileSync(`${root}/powershell/assets/steps/${f}.json`, "utf8")).Steps) cat[s.Id] = s
const goals = JSON.parse(fs.readFileSync(`${root}/powershell/assets/steps/goals.json`, "utf8")).Goals
const W = { Critical: 4, High: 3, Medium: 2, Low: 1, Info: 0 }

const measures = {
  "devices-compliant": { Key: "devices-compliant", Count: 412, Total: 580, Share: 71, MinimumShare: 95, Met: false, ReadAt: "2026-11-02T09:52:10+11:00",
    Caveat: "Devices that aren't registered or joined in Microsoft Entra ID can't be counted.", ObjectCount: 168,
    Objects: ["DESKTOP-4KQ2M1", "LAPTOP-ADELE", "LAPTOP-ALEXW", "MAC-BOBLEAF", "iPhone (Diego)", "DESKTOP-FIN-07", "LAPTOP-GAEL", "Pixel 8 (Isaiah)", "DESKTOP-HR-02", "LAPTOP-LEEGU", "MAC-MEGAN", "DESKTOP-RECEPT", "SURFACE-NESTOR", "LAPTOP-PATTI"].map((n, i) => ({ Type: "Device", Id: `device-${i}`, DisplayName: n })), ReasonCode: null },
  "mfa-capable": { Key: "mfa-capable", Count: 1187, Total: 1213, Share: 98, MinimumShare: 95, Met: true, ReadAt: "2026-11-02T09:52:12+11:00",
    Caveat: "Leaves out guests and the emergency access and directory sync accounts.", ObjectCount: 26,
    Objects: ["Bagul Atayewa", "Damien Bowden", "Joshua Fernando", "Tyler Chan"].map((n, i) => ({ Type: "User", Id: `user-${i}`, DisplayName: n })), ReasonCode: null },
}
const hybrid = true
// What an earlier run in the output folder said (LastKnown), for steps this run did not check.
const earlier = { "entra.password-hash-sync": { Status: "Done", ExecutedAt: "2026-10-26T09:10:44+11:00", File: "TestResults-2026-10-26-091044.json" } }

function build(rows, overrides = {}) {
  const byId = new Map(rows.map((t) => [t.Id, t]))
  const named = new Map()
  for (const [id, steps] of Object.entries(inventory)) for (const s of steps) { if (!named.has(s)) named.set(s, []); named.get(s).push(id) }
  const prereqs = (s) => [...(s.Requires || []), ...(s.RequiresOneOf || []).flat(), ...(s.RecommendedFirst || [])]
  const scope = new Set()
  const add = (id) => { if (scope.has(id) || !cat[id]) return; scope.add(id); for (const p of prereqs(cat[id])) add(p) }
  for (const t of rows) if (t.Result !== "NotRun") for (const s of inventory[t.Id] || []) add(s)
  const status = {}, reason = {}, tests = {}
  for (const id of scope) {
    const s = cat[id]
    tests[id] = (named.get(id) || []).map((tid) => { const r = byId.get(tid); return r ? { Id: tid, Result: r.Result, ...(r.ReasonCode ? { ReasonCode: r.ReasonCode } : {}) } : { Id: tid, Result: "NotRun", ReasonCode: "NotInRun" } })
    const ran = tests[id].filter((t) => t.Result !== "NotRun")
    const m = s.Measure ? measures[s.Measure.Key] : null
    if ((s.OnlyWhen || []).includes("hybrid-identity") && !hybrid) status[id] = "NotApplicable"
    else if (ran.length && ran.every((t) => t.ReasonCode === "NotApplicable")) status[id] = "NotApplicable"
    else if (ran.some((t) => t.Result === "Failed") || (m && m.ReasonCode === null && !m.Met)) status[id] = "NotDone"
    else if (ran.some((t) => ["Investigate", "Error", "Skipped"].includes(t.Result)) || (m && m.ReasonCode)) status[id] = "Unknown"
    else if (ran.length || m) status[id] = "Done"
    else { status[id] = "NotChecked"; reason[id] = tests[id].length ? "NotSelected" : "NoCheck" }
    if (overrides[id]) Object.assign(status, { [id]: overrides[id] })
  }
  const met = (p) => status[p] === "Done" || status[p] === "NotApplicable" || !scope.has(p)
  const steps = [...scope].map((id) => {
    const s = cat[id]
    const st = status[id]
    let readiness = null, blockedBy = [], unconfirmed = []
    if (st !== "Done" && st !== "NotApplicable") {
      for (const p of s.Requires || []) { if (status[p] === "NotDone") blockedBy.push(p); else if (!met(p)) unconfirmed.push(p) }
      for (const g of s.RequiresOneOf || []) {
        const left = g.filter((p) => status[p] !== "NotApplicable")
        if (!left.length || left.some((p) => status[p] === "Done")) continue
