.mt-kpi.click button.mt-kchip, .mt-kpi.click a.mt-kchip { pointer-events: auto; }

/* Tables in a finding wrap between words, never inside one, and scroll sideways when they need more room than the
   sheet has (#2610). Headers stay on one line. */
.mt-md table { width: max-content; min-width: 0; }
.mt-md th { white-space: nowrap; }
.mt-md td { overflow-wrap: break-word; word-break: normal; min-width: 4em; max-width: 36em; vertical-align: top; }
/* A shadow on the side a table can still scroll towards. */
.mt-md table {
  background:
    linear-gradient(to right, var(--mt-paper) 30%, transparent) left / 40px 100% no-repeat local,
    linear-gradient(to left, var(--mt-paper) 30%, transparent) right / 40px 100% no-repeat local,
    radial-gradient(farthest-side at 0 50%, color-mix(in srgb, var(--mt-ink) 22%, transparent), transparent) left / 12px 100% no-repeat scroll,
    radial-gradient(farthest-side at 100% 50%, color-mix(in srgb, var(--mt-ink) 22%, transparent), transparent) right / 12px 100% no-repeat scroll;
}

/* The GitHub mark is black (website/public/report-icons/v1/products/README.md): white in dark mode. */
.dark img.mt-pm[data-product="github"] {
  filter: invert(1);
}
