/* Defender's path (components/report/path.tsx): step cards in three groups, a lane for each goal, the overview
   card, and "Before you fix this" on a test page. */
.mt-badge.warn { background: var(--mt-warn-bg); color: var(--mt-warn-ink); }
.mt-step { display: flex; flex-direction: column; gap: 12px; padding: 16px 18px; min-width: 0; scroll-margin-top: 72px; }
.mt-step-h { display: grid; grid-template-columns: 18px minmax(0, 1fr) auto; gap: 10px; align-items: start; }
.mt-step-h .mt-pm { margin-top: 2px; }
.mt-step-h b { font-weight: 650; font-size: 14.5px; line-height: 1.35; }
.mt-step-tags { display: flex; gap: 6px; flex-wrap: wrap; justify-content: flex-end; }
.mt-step-sum { margin: 0; font-size: 13px; color: var(--mt-ink-2); }
.mt-stepline { display: flex; flex-wrap: wrap; gap: 4px 10px; align-items: baseline; font-size: 13px; color: var(--mt-ink-2); }
.mt-stepline > b { font: 600 11px var(--mt-mono); letter-spacing: .06em; text-transform: uppercase; color: var(--mt-ink-3); flex-basis: 100%; }
.mt-stepline.bad > b { color: var(--mt-fail-ink); }
.mt-stepline.good > b { color: var(--mt-pass-ink); }
.mt-stepline .mt-cmd { flex-basis: 100%; }
.mt-steplink { border: 0; background: none; padding: 0; text-align: left; color: var(--mt-ember-ink); font-weight: 550; }
.mt-steplink:hover { text-decoration: underline; text-underline-offset: 2px; }
.mt-steptests { display: flex; flex-wrap: wrap; gap: 6px 14px; align-items: center; border-top: 1px solid var(--mt-line-2); padding-top: 10px; }
.mt-steptests > .mt-note { flex-basis: 100%; }
.mt-steptest { display: inline-flex; gap: 7px; align-items: center; }
.mt-measure { display: flex; flex-direction: column; gap: 7px; border: 1px solid var(--mt-line); background: var(--mt-canvas); border-radius: 10px; padding: 10px 12px; min-width: 0; }
.mt-measure-h { display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; font-size: 13px; }
.mt-measure-h b { font-weight: 600; }
.mt-measure-h .mt-num { font-weight: 600; }
.mt-meter { position: relative; height: 8px; border-radius: 99px; background: var(--mt-subtle); border: 1px solid var(--mt-line-2); }
.mt-meter i { position: absolute; inset: 0 auto 0 0; border-radius: 99px; background: var(--mt-fail); }
.mt-meter i.met { background: var(--mt-pass); }
.mt-meter b { position: absolute; top: -4px; bottom: -4px; width: 2px; margin-left: -1px; background: var(--mt-ink); border-radius: 2px; }
.mt-more summary { cursor: pointer; font-size: 13px; font-weight: 550; color: var(--mt-ink-2); }
.mt-more summary:hover { color: var(--mt-ink); }
.mt-more[open] summary { margin-bottom: 8px; }
.mt-objlist { margin: 0 0 6px; padding: 0; list-style: none; display: flex; flex-wrap: wrap; gap: 4px; }
.mt-objlist li { font-size: 12px; border: 1px solid var(--mt-line); border-radius: 6px; padding: 1px 7px; background: var(--mt-paper); overflow-wrap: anywhere; }
.mt-rollout { margin: 0 0 10px; padding-left: 20px; font-size: 13px; line-height: 1.6; color: var(--mt-ink-2); list-style: decimal; }
.mt-sources { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 8px; }
.mt-sources li { display: flex; flex-direction: column; gap: 2px; font-size: 12.5px; color: var(--mt-ink-3); min-width: 0; }
.mt-sources a { overflow-wrap: anywhere; }
.mt-lanes { display: flex; flex-direction: column; }
.mt-lane { display: flex; flex-direction: column; gap: 10px; padding: 14px 18px; border-top: 1px solid var(--mt-line-2); }
.mt-lane:first-child { border-top: 0; }
.mt-lane-h { display: flex; justify-content: space-between; gap: 10px; align-items: baseline; flex-wrap: wrap; font-size: 13.5px; }
.mt-lane-h b { font-weight: 650; }
.mt-lane-steps { display: flex; flex-wrap: wrap; gap: 8px; margin: 0; padding: 0; list-style: none; counter-reset: lane; }
.mt-lane-steps li { position: relative; display: grid; grid-template-columns: 9px minmax(0, 1fr); gap: 2px 8px; align-items: center; border: 1px solid var(--mt-line); border-radius: 10px; padding: 6px 10px; font-size: 12.5px; max-width: 260px; background: var(--mt-paper); }
.mt-lane-steps li > i { width: 9px; height: 9px; border-radius: 99px; background: var(--mt-skip); grid-row: span 2; align-self: start; margin-top: 5px; }
.mt-lane-steps li > button, .mt-lane-steps li > span { border: 0; background: none; padding: 0; text-align: left; line-height: 1.35; font-weight: 550; color: var(--mt-ink); }
.mt-lane-steps li > button:hover { color: var(--mt-ember-ink); }
.mt-lane-steps li > small { grid-column: 2; font-size: 11.5px; color: var(--mt-ink-3); }
.mt-lane-steps li + li::before { content: "→"; position: absolute; left: -8px; top: 50%; transform: translate(-50%, -50%); font-size: 11px; color: var(--mt-ink-3); }
.mt-lane-steps .st-Done > i { background: var(--mt-pass); }
.mt-lane-steps .st-NotDone > i { background: var(--mt-fail); }
.mt-lane-steps .st-Unknown > i { background: var(--mt-inv); }
.mt-lane-steps .st-NotChecked > i { background: transparent; border: 1.5px solid var(--mt-skip); }
.mt-lane-steps .st-none { border-style: dashed; }
.mt-lane-steps .st-none > span, .mt-lane-steps .st-NotApplicable > span { color: var(--mt-ink-3); font-weight: 500; }
.mt-pathcounts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px 18px; }
.mt-pathcounts .mt-count:hover b { text-decoration: underline; text-underline-offset: 3px; }
.mt-before { display: flex; flex-direction: column; gap: 12px; border: 1px solid var(--mt-warn-bg); border-left: 3px solid var(--mt-warn); border-radius: 12px; padding: 14px 16px; background: var(--mt-paper); }
.mt-before h3 { margin: 0; }
.mt-before-lead { margin: 0; font-size: 13.5px; color: var(--mt-ink-2); }
.mt-prereqs { display: flex; flex-direction: column; }
.mt-prereq { display: flex; flex-direction: column; gap: 6px; padding: 9px 0; border-top: 1px solid var(--mt-line-2); min-width: 0; }
.mt-prereq:first-child { border-top: 0; padding-top: 0; }
.mt-prereq-h { display: flex; flex-wrap: wrap; gap: 4px 10px; align-items: center; font-size: 13px; }
.mt-prereq-h b { font-weight: 600; }
@media (max-width: 640px) {
  .mt-step-h { grid-template-columns: 18px minmax(0, 1fr); }
  .mt-step-tags { grid-column: 2; justify-content: flex-start; }
  .mt-lane-steps { flex-direction: column; }
  .mt-lane-steps li { max-width: none; }
  .mt-lane-steps li + li::before { content: "↓"; left: 18px; top: -5px; }
}
EOF

